86	    /**
87	     * An owner's {@code locality}, now the REGION component of its region-and-hash {@code customerCode}
88	     * ({@code <REGION>-<HASH8>}). When the code is absent or not yet in that shape (e.g. an owner not
89	     * created through the region-and-hash pipeline), falls back to deriving the region from the city
90	     * and postcode directly.
91	     */
92	    public static String localityOfCustomerCode(String customerCode, String city, String postcode) {
93	        if (customerCode != null) {
94	            int dash = customerCode.indexOf('-');
95	            if (dash > 0) {
96	                return customerCode.substring(0, dash);
97	            }
98	        }
99	        return localityOf(city, postcode);
100	    }
101	
102	    /**
103	     * The IANA timezone name for the owner's locality/region, derived the same way as
104	     * {@link #localityOfCustomerCode(String, String, String)}, via the fixed region-to-timezone
105	     * table (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane).
106	     * Returns {@code null} when the region is {@code "UNKNOWN"} (not in the table).
107	     */
108	    public static String timezoneOfCustomerCode(String customerCode, String city, String postcode) {
109	        return REGION_TIMEZONE.get(localityOfCustomerCode(customerCode, city, postcode));
110	    }
111	}
