18	/**
19	 * Maps Owner & OwnerDto using Mapstruct.
20	 *
21	 * <p>The {@code membershipLevel} is derived from the owner's fields together with the size of its
22	 * household (see {@link MembershipLevel}), so the mapper needs the {@link OwnerRepository}.
23	 */
24	@Mapper(uses = PetMapper.class)
25	public abstract class OwnerMapper {
26	
27	    @Autowired
28	    protected OwnerRepository ownerRepository;
29	
30	    /** Household-aware membership points, called from the {@code membershipPoints} mapping expression. */
31	    protected int membershipPoints(Owner owner) {
32	        return MembershipLevel.points(owner, this.ownerRepository);
33	    }
34	
35	    /** Household-aware membership level, called from the {@code membershipLevel} mapping expression. */
36	    protected int membershipLevel(Owner owner) {
37	        return MembershipLevel.of(owner, this.ownerRepository);
38	    }
39	
40	    @Mapping(target = "displayName",
41	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
42	    @Mapping(target = "salutation",
43	        expression = "java(owner.getTitle() == null || owner.getTitle().isBlank() ? owner.getLastName() : owner.getTitle() + \" \" + owner.getLastName())")
44	    @Mapping(target = "initials",
45	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
46	    @Mapping(target = "telephoneDisplay",
47	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneE164.display(owner.getTelephone()))")
48	    @Mapping(target = "membershipPoints",
49	        expression = "java(membershipPoints(owner))")
50	    @Mapping(target = "membershipLevel",
51	        expression = "java(membershipLevel(owner))")
52	    @Mapping(target = "locality",
